"""Generate the §5 format-support matrix FROM the adapter registry (doc-from-code, §8).

The docs cannot drift from the code because they ARE the code's registry, rendered. The
output is a LIVING generated doc — never hand-edit it; re-run this generator.
"""
from __future__ import annotations

from .registry import REGISTRY, AdapterRegistry


def generate_matrix(registry: AdapterRegistry = REGISTRY) -> str:
    lines = [
        "<!-- GENERATED by databridge_convert.router.matrix — DO NOT HAND-EDIT. -->",
        "# Format-Support Matrix (generated from the adapter registry)",
        "",
        "Source of truth: the `AdapterInfo` registry (09_FINAL_PRD §5/§8). Regenerate with",
        "`python -m databridge_convert.router.matrix`. Grows as adapters land.",
        "",
        "| Format | R | W | IR | Modality | Lossless? | Limits |",
        "|---|---|---|---|---|---|---|",
    ]
    for a in registry.all():
        r = "✓" if a.can_read else "—"
        w = "✓" if a.can_write else "—"
        lossless = "yes" if a.lossiness == "lossless" else "lossy"
        limits = "; ".join(a.limits) if a.limits else ""
        lines.append(f"| {a.format} | {r} | {w} | {a.ir} | {a.modality} | {lossless} | {limits} |")
    lines.append("")
    lines.append(f"_Total registered adapters: {len(registry.all())}._")
    return "\n".join(lines) + "\n"


def main() -> None:
    # importing the adapters package registers every adapter
    from .. import adapters  # noqa: F401
    print(generate_matrix())


if __name__ == "__main__":
    main()
